-- Cadastro das fichas de 2025, copiado da aba "5 Despesa" da planilha (colunas A a J), na mesma ordem.
-- Para um novo exercício, gere um arquivo igual com o orçamento aprovado do ano.
on conflict (exercicio, ficha) do update set
  grupo = excluded.grupo, acao = excluded.acao, acao_nome = excluded.acao_nome, natureza_desc = excluded.natureza_desc,
  marcador = excluded.marcador, tipo_ficha = excluded.tipo_ficha, fonte = excluded.fonte, programa = excluded.programa,
  fonte_caixa = excluded.fonte_caixa, categoria = excluded.categoria, orcado = excluded.orcado, ordem = excluded.ordem;
